try (PreparedStatement ps = conn.prepareStatement("INSERT INTO items VALUES (?,?)")) {
  ps.setInt(1,1); ps.setString(2,"a"); ps.addBatch();
  ps.setInt(1,1); ps.setString(2,"b"); ps.addBatch(); // duplikat
  ps.setInt(1,2); ps.setString(2,"c"); ps.addBatch();
  ps.executeBatch();
} catch (BatchUpdateException e) {
  int[] counts = e.getUpdateCounts();
  int success = 0;
  for (int c : counts) if (c != Statement.EXECUTE_FAILED) success++;
  System.out.println(success + " z " + counts.length + " operacji w paczce powiodlo sie");
}

