List<String[]> source = generateFakeData(8000);
long totalStart = System.nanoTime();
int chunkCount = 0;
for (int i = 0; i < source.size(); i += 500) {
  List<String[]> chunk = source.subList(i, Math.min(i+500, source.size()));
  conn.setAutoCommit(false);
  try (PreparedStatement ps = conn.prepareStatement("INSERT INTO items VALUES (?,?,?)")) {
    for (String[] row : chunk) { ps.setInt(1, Integer.parseInt(row[0])); ps.setString(2, row[1]); ps.setBigDecimal(3, new BigDecimal(row[2])); ps.addBatch(); }
    ps.executeBatch();
    conn.commit();
  } finally { conn.setAutoCommit(true); }
  chunkCount++;
}
long totalTime = (System.nanoTime()-totalStart)/1_000_000;
System.out.println(chunkCount + " porcji, " + totalTime + "ms, " + (8000.0/totalTime*1000) + " wierszy/s");
